prompt.text:
Repair the complete CommonJS source below and return a corrected complete source file. It must export exactly `{ parseLaunchLink }`.

`parseLaunchLink(text)` accepts a string containing an absolute link shaped as `desk://run/<command>?<parameters>`. It must throw `TypeError` for a non-string and `RangeError` for an invalid URL, a different protocol or host, an empty command, or duplicate query keys. The command is the decoded pathname without its single leading slash. Return `{ command, parameters }`, where `parameters` is a new ordinary object containing decoded query values in source order. An empty query yields `{}`. Fragment identifiers are ignored. No mutable state may be shared between calls.

Known-bad source:
```javascript
'use strict';

function parseLaunchLink(text) {
  if (typeof text !== 'string') throw new TypeError('text must be a string');
  let url;
  try {
    url = new URL(text);
  } catch (error) {
    throw new RangeError('invalid link');
  }
  if (url.protocol !== 'desk' || url.hostname !== 'run') {
    throw new RangeError('unsupported link');
  }
  const command = decodeURIComponent(url.pathname.slice(1));
  if (command.length === 0) throw new RangeError('missing command');
  const parameters = {};
  for (const [key, value] of url.searchParams) {
    if (Object.prototype.hasOwnProperty.call(parameters, key)) {
      throw new RangeError('duplicate parameter');
    }
    parameters[key] = value;
  }
  return { command, parameters };
}

module.exports = { parseLaunchLink };
```

