'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepEqual(Object.keys(api), ['parseLaunchLink']);
const { parseLaunchLink } = api;

assert.deepEqual(parseLaunchLink('desk://run/build'), { command: 'build', parameters: {} });
assert.deepEqual(parseLaunchLink('desk://run/open%20file?path=a%2Fb&mode=fast#ignored'), {
  command: 'open file',
  parameters: { path: 'a/b', mode: 'fast' }
});
assert.deepEqual(parseLaunchLink('desk://run/a/b?first=1&empty=&space=a+b'), {
  command: 'a/b',
  parameters: { first: '1', empty: '', space: 'a b' }
});
const ordered = parseLaunchLink('desk://run/go?z=1&a=2&m=3');
assert.deepEqual(Object.keys(ordered.parameters), ['z', 'a', 'm']);
assert.equal(Object.getPrototypeOf(ordered.parameters), Object.prototype);
const special = parseLaunchLink('desk://run/go?__proto__=safe&constructor=value');
assert.equal(Object.getPrototypeOf(special.parameters), Object.prototype);
assert.deepEqual(Object.keys(special.parameters), ['__proto__', 'constructor']);
assert.equal(special.parameters.__proto__, 'safe');
assert.equal(special.parameters.constructor, 'value');

assert.throws(() => parseLaunchLink(null), TypeError);
assert.throws(() => parseLaunchLink({}), TypeError);
for (const text of [
  'not a url',
  '/relative',
  'http://run/go',
  'desk://other/go',
  'desk://run',
  'desk://run/',
  'desk://run/%E0%A4%A',
  'desk://run/go?a=1&a=2',
  'desk://run/go?a=1&%61=2'
]) {
  assert.throws(() => parseLaunchLink(text), RangeError, text);
}
const one = parseLaunchLink('desk://run/go?x=1');
const two = parseLaunchLink('desk://run/go?x=1');
assert.notStrictEqual(one, two);
assert.notStrictEqual(one.parameters, two.parameters);
one.parameters.x = 'changed';
assert.equal(two.parameters.x, '1');

